#!/usr/bin/env node
// Generated by Squad from the Squad SDK (claude-plugin.ts). Do not edit: run `node scripts/build-claude-plugin.mjs`.
//
// Squad plugin launcher. Runs the Squad CLI with this process's arguments, resolved in this order:
//   1. SQUAD_CLI (a command, or a .js entry run with this Node)
//   2. the project's own install: node_modules/@bradygaster/squad-cli
//   3. a `squad` on PATH (never this plugin's own bin/)
//   4. npx -y @bradygaster/squad-cli@<this plugin's version>
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PKG = '@bradygaster/squad-cli';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ownBin = path.join(root, 'bin');
const win = process.platform === 'win32';

function pluginVersion() {
  try {
    return JSON.parse(fs.readFileSync(path.join(root, '.claude-plugin', 'plugin.json'), 'utf8')).version;
  } catch {
    return undefined;
  }
}

function onPath(name) {
  const exts = win ? (process.env.PATHEXT || '.EXE;.CMD;.BAT').split(';') : [''];
  for (const dir of (process.env.PATH || '').split(path.delimiter)) {
    if (!dir || path.resolve(dir) === ownBin) continue;
    for (const ext of exts) {
      const file = path.join(dir, name + ext);
      try {
        if (fs.statSync(file).isFile()) return file;
      } catch {
        // not here
      }
    }
  }
  return undefined;
}

function resolveCli() {
  const override = process.env.SQUAD_CLI;
  if (override) return /\.[cm]?js$/.test(override) ? [process.execPath, [override]] : [override, []];
  const project = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const local = path.join(project, 'node_modules', ...PKG.split('/'), 'dist', 'cli-entry.js');
  if (fs.existsSync(local)) return [process.execPath, [local]];
  const global = onPath('squad');
  if (global) return [global, []];
  const version = pluginVersion();
  return [win ? 'npx.cmd' : 'npx', ['-y', version ? `${PKG}@${version}` : PKG]];
}

const [command, prefix] = resolveCli();
const child = spawn(command, [...prefix, ...process.argv.slice(2)], {
  stdio: 'inherit',
  shell: win && /\.(cmd|bat)$/i.test(command),
});
for (const signal of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(signal, () => child.kill(signal));
child.on('error', (err) => {
  process.stderr.write(`squad plugin: cannot start the Squad CLI (${err.message}). Install it with: npm install -g ${PKG}\n`);
  process.exit(1);
});
child.on('exit', (code, signal) => process.exit(code ?? (signal ? 1 : 0)));
